# Generated by manage.py generate_test_cases.
from urllib.parse import parse_qs, urlsplit
from uuid import uuid4

from bs4 import BeautifulSoup
from django.contrib.auth.models import Group, Permission
from django.http import HttpResponse
from django.test import RequestFactory

from bloomerp.filters.definition import FilterCondition
from bloomerp.models.workspaces.sql_query import SqlQuery
from bloomerp.permissions.definition import BloomerpPermission, RowPolicyRuleContent
from bloomerp.permissions.manager import PolicyManager
from bloomerp.templatetags.bloomerp import render_object_action
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestExecuteSqlQueryComponent(BloomerpComponentTestCase):
    """Cover saved-query modal execution and the existing posted SQL contract."""

    view_name = 'components_execute_sql_query'
    auto_create_customers = False

    def setUp(self) -> None:
        """Create a saved read-only query and select its configured Apply action."""
        super().setUp()
        self.saved_query = SqlQuery.objects.create(name="Answer", query="SELECT 42 AS answer;")
        self.action = SqlQuery.bloomerp_config.object_actions[0]

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Exercise modal loading, input validation, and row/field execution permissions."""
        saved = {"query_id": str(self.saved_query.pk)}
        denied = ExpectedResult(status_code=403, response_validators=self.action_is_hidden)
        results = ExpectedResult(response_validators=self.has_query_results)
        return [
            RequestScenario(name="Saved-query execution requires login", query_params=saved,
                            expected=ExpectedResult(status_code=302)),
            RequestScenario(name="Superuser loads saved results into the modal", user=self.admin_user,
                            query_params=saved, expected=results),
            RequestScenario(name="Editor can still post SQL", method="POST", user=self.admin_user,
                            data={"sql_query": self.saved_query.query}, expected=results),
            RequestScenario(name="GET cannot execute arbitrary supplied SQL", user=self.admin_user,
                            query_params={"sql_query": self.saved_query.query}, expected=ExpectedResult(status_code=400)),
            RequestScenario(name="Malformed saved-query ID is rejected", user=self.admin_user,
                            query_params={"query_id": "invalid"}, expected=ExpectedResult(status_code=400)),
            RequestScenario(name="Unknown saved-query ID is rejected", user=self.admin_user,
                            query_params={"query_id": str(uuid4())}, expected=ExpectedResult(status_code=404)),
            RequestScenario(name="No-policy user cannot apply a query", user=self.normal_user,
                            query_params=saved, expected=denied),
            RequestScenario(name="Execution permission alone cannot read saved SQL", user=self.normal_user,
                            query_params=saved, prepare=self.grant_execution, expected=denied),
            RequestScenario(name="Reading SQL does not grant execution", user=self.normal_user,
                            query_params=saved, prepare=self.grant_query_read, expected=denied),
            RequestScenario(name="Name-only access cannot execute the hidden SQL field", user=self.normal_user,
                            query_params=saved, prepare=[self.grant_execution, self.grant_name_read], expected=denied),
            RequestScenario(name="Another row's policy cannot expose this query", user=self.normal_user,
                            query_params=saved, prepare=[self.grant_execution, self.grant_other_query_read], expected=denied),
            RequestScenario(name="Authorized policy user can apply the query", user=self.normal_user,
                            query_params=saved, prepare=[self.grant_execution, self.grant_query_read], expected=results),
            RequestScenario(name="Group policies authorize saved-query execution", user=self.normal_user,
                            query_params=saved, prepare=[self.grant_execution, self.grant_group_query_read], expected=results),
            RequestScenario(name="Saved queries retain read-only validation", user=self.admin_user,
                            query_params=saved, prepare=self.make_query_unsafe, expected=ExpectedResult(status_code=400)),
            RequestScenario(name="Unsupported methods are rejected", method="DELETE", user=self.admin_user,
                            expected=ExpectedResult(status_code=405)),
        ]

    def grant_execution(self, scenario: RequestScenario) -> None:
        """Grant the existing custom SQL execution capability to the scenario user."""
        scenario.user.user_permissions.add(Permission.objects.get(
            content_type__app_label="bloomerp", content_type__model="sqlquery", codename="execute_sql_query",
        ))

    def assign_read_policy(self, field: str, *, other_row: bool = False, group: bool = False) -> None:
        """Grant one field on one saved-query row through the standard policy manager."""
        policy = PolicyManager.create_policy(
            SqlQuery,
            field_permissions={field: [BloomerpPermission.VIEW]},
            row_permissions=[RowPolicyRuleContent(
                connector="AND", permissions=[BloomerpPermission.VIEW],
                conditions=[FilterCondition(
                    field_path="id", lookup_id="equals", value=str(uuid4() if other_row else self.saved_query.pk),
                )],
            )],
            global_permissions=[BloomerpPermission.VIEW],
        )
        if group:
            subject = Group.objects.create(name="SQL readers")
            self.normal_user.groups.add(subject)
        else:
            subject = self.normal_user
        PolicyManager.assign(policy, subject)

    def grant_query_read(self, scenario: RequestScenario) -> None:
        """Permit the current saved query's SQL field."""
        self.assign_read_policy("query")

    def grant_name_read(self, scenario: RequestScenario) -> None:
        """Permit the saved query row while keeping its SQL field hidden."""
        self.assign_read_policy("name")

    def grant_other_query_read(self, scenario: RequestScenario) -> None:
        """Permit the SQL field only for a different query identifier."""
        self.assign_read_policy("query", other_row=True)

    def grant_group_query_read(self, scenario: RequestScenario) -> None:
        """Permit the saved query via an assigned group policy."""
        self.assign_read_policy("query", group=True)

    def make_query_unsafe(self, scenario: RequestScenario) -> None:
        """Store a non-read-only statement to exercise the executor's safety gate."""
        SqlQuery.objects.filter(pk=self.saved_query.pk).update(query="DELETE FROM sql_query;")

    def has_query_results(self, response: HttpResponse) -> bool:
        """Verify the real executor rendered the expected saved or posted SQL result."""
        return (
            response.context["columns"] == ["answer"]
            and response.context["rows"] == [{"answer": 42}]
            and 'data-sql-results-meta' in response.content.decode()
        )

    def action_is_hidden(self, response: HttpResponse) -> bool:
        """Hide Apply whenever the corresponding execution request would be denied."""
        return render_object_action(self.action, self.saved_query, response.wsgi_request) == ""

    def test_apply_action_targets_the_results_modal(self) -> None:
        """Render the actual action button with a saved-query URL and modal attributes."""
        request = RequestFactory().get("/")
        request.user = self.admin_user
        html = render_object_action(self.action, self.saved_query, request)
        button = BeautifulSoup(html, "html.parser").select_one("button")
        self.assertIsNotNone(button)
        endpoint = urlsplit(button["hx-get"])
        self.assertEqual(endpoint.path, self.get_endpoint(self.view_name, None))
        self.assertEqual(parse_qs(endpoint.query), {"query_id": [str(self.saved_query.pk)]})
        self.assertEqual(button["hx-target"], "#bloomerp-general-use-modal-body")
        self.assertEqual(button["bloomerp-open-modal"], "bloomerp-general-use-modal")
        self.assertEqual(button["bloomerp-set-modal-size-to"], "xl")
